(()=>{const r=document.getElementById('sideline-preview'),$=s=>r.querySelector(s);let state={periods:4,minutes:8,period:1,remain:480,running:false,last:Date.now(),p:[0,0,0,0],active:[false,false,false,false],armed:[false,false,false,false]};try{const saved=JSON.parse(localStorage.getItem('resolute-iphone'));if(saved&&Array.isArray(saved.p)&&saved.p.length===4)state={...state,...saved}}catch(e){}let ctx,horn=new Audio('horn.wav'),wake;
const fmt=n=>{n=Math.ceil(Math.max(0,n));return String(Math.floor(n/60)).padStart(2,'0')+':'+String(n%60).padStart(2,'0')};const save=()=>{try{localStorage.setItem('resolute-iphone',JSON.stringify(state))}catch(e){}};
function unlock(){if(!ctx)ctx=new(window.AudioContext||window.webkitAudioContext)();ctx.resume().catch(()=>{});if('wakeLock'in navigator&&!wake)navigator.wakeLock.request('screen').then(w=>{wake=w;w.addEventListener('release',()=>wake=null)}).catch(()=>{});}
function beep(delay=0){if(!ctx||ctx.state!=='running')return;const o=ctx.createOscillator(),g=ctx.createGain(),t=ctx.currentTime+delay;o.type='square';o.frequency.value=1000;g.gain.setValueAtTime(.0001,t);g.gain.exponentialRampToValueAtTime(.12,t+.008);g.gain.exponentialRampToValueAtTime(.0001,t+.09);o.connect(g);g.connect(ctx.destination);o.start(t);o.stop(t+.1)}
function clapMinute(){if(!ctx||ctx.state!=='running')return;const duration=.18,buffer=ctx.createBuffer(1,Math.ceil(ctx.sampleRate*duration),ctx.sampleRate),data=buffer.getChannelData(0);for(let i=0;i<data.length;i++){const t=i/ctx.sampleRate;const attack=Math.min(1,t/.002);const bursts=1+.4*Math.cos(2*Math.PI*90*t);data[i]=(Math.random()*2-1)*attack*Math.exp(-t*30)*bursts}for(const delay of[0,.35]){const source=ctx.createBufferSource(),filter=ctx.createBiquadFilter(),gain=ctx.createGain();source.buffer=buffer;filter.type='highpass';filter.frequency.value=600;gain.gain.value=.85;source.connect(filter);filter.connect(gain);gain.connect(ctx.destination);source.start(ctx.currentTime+delay)}}
function soundZero(game){if(game){horn.currentTime=0;horn.play().catch(()=>{if(!ctx)return;for(const f of [220,277,440]){const o=ctx.createOscillator(),g=ctx.createGain();o.type='sawtooth';o.frequency.value=f;g.gain.value=.12;o.connect(g);g.connect(ctx.destination);o.start();o.stop(ctx.currentTime+1.8)}})}else{beep();beep(.16);beep(.32)}}
function cue(before,after){const a=Math.ceil(before),b=Math.ceil(after);return a>b&&b<=10?(b===0?2:1):0}
function advance(audio=false){const now=Date.now(),dt=Math.max(0,(now-state.last)/1000),gameDt=state.running?Math.min(dt,state.remain):0;let c=0,ended=false,minuteAlert=false;if(state.running){const before=state.remain;state.remain=Math.max(0,state.remain-dt);c=cue(before,state.remain);minuteAlert=before>60&&state.remain<=60&&state.remain>0;ended=before>0&&state.remain===0}for(let i=0;i<4;i++)if(state.armed[i]){const before=state.p[i];state.p[i]=Math.max(0,before-gameDt);c=Math.max(c,cue(before,state.p[i]))}if(!state.remain)state.running=false;state.last=now;if(audio&&dt<1.5&&document.visibilityState==='visible'){if(ended)soundZero(true);else if(minuteAlert){clapMinute();if(c===2)soundZero(false);else if(c===1)beep()}else if(c===2)soundZero(false);else if(c===1)beep()}}
function act(fn){unlock();advance();fn();state.last=Date.now();render();save()}
for(const[id,values]of[['length',[1,2,3,4,5]],['minutes',[5,8,12,15]]])for(const n of values){const b=document.createElement('button');b.textContent=n;b.dataset.n=n;b.onclick=()=>act(()=>{if(id==='length'){state.periods=n;state.period=Math.min(state.period,n)}else{state.minutes=n;state.remain=n*60;state.running=false}});$('#'+id).append(b)}
for(let i=0;i<4;i++){const box=document.createElement('div');box.className='pen';box.innerHTML='<div class="small">PENALTY '+(i+1)+'</div><div class="penclock">00:00</div><div class="small state">EMPTY</div>';const times=document.createElement('div');times.className='times';box.append(times);for(const sec of[30,60,120,180]){const b=document.createElement('button');b.textContent=fmt(sec);b.onclick=()=>act(()=>{state.p[i]=sec;state.active[i]=true;state.armed[i]=false});times.append(b)}for(const label of['+5','Clear']){const b=document.createElement('button');b.textContent=label;b.onclick=()=>act(()=>{if(label==='Clear'){state.p[i]=0;state.active[i]=false;state.armed[i]=false}else{if(state.p[i]===0)state.armed[i]=false;state.p[i]+=5;state.active[i]=true}});box.append(b)}$('#penalties').append(box)}
function message(){return 'Lacrosse Final Score · Field '+field+'\n'+($('#team1').value.trim()||fieldDefaults(field)[0])+': '+Math.max(0,parseInt($('#score1').value)||0)+'\n'+($('#team2').value.trim()||fieldDefaults(field)[1])+': '+Math.max(0,parseInt($('#score2').value)||0)}
function render(){$('#game').textContent=fmt(state.remain);$('#period').textContent='PERIOD '+state.period+' / '+state.periods;$('#start').textContent=state.running?'Ⅱ PAUSE':'▶ START';$('#status').textContent=state.running?'RUNNING':state.remain===0?'ENDED':'READY';$('#prev').disabled=state.period===1;$('#next').disabled=state.period===state.periods;const armed=state.armed.some((a,i)=>a&&state.p[i]>0);$('#all').textContent=armed?'Ⅱ Pause All Penalties':'▶ Start All Penalties';$('#mode').textContent=armed?(state.running?'COUNTING DOWN':'PAUSED BY MASTER'):'WAITING FOR START';for(const id of['length','minutes'])$('#'+id).querySelectorAll('button').forEach(b=>b.classList.toggle('selected',+b.dataset.n===state[id==='length'?'periods':'minutes']));$('#penalties').querySelectorAll('.pen').forEach((b,i)=>{b.querySelector('.penclock').textContent=fmt(state.p[i]);b.querySelector('.state').textContent=!state.active[i]?'EMPTY':state.p[i]===0?'COMPLETE':state.armed[i]?(state.running?'COUNTING DOWN':'PAUSED BY MASTER'):'SET / WAITING'});$('#message-title').textContent='Lacrosse Final Score · Field '+field;for(let side=1;side<=2;side++){$('#message-team'+side).textContent=($('#team'+side).value.trim()||fieldDefaults(field)[side-1])+':';$('#message-score'+side).textContent=Math.max(0,parseInt($('#score'+side).value)||0)}}
for(const[id,delta]of[['game-minus',-1],['game-plus',1]])$('#'+id).onclick=()=>act(()=>{state.remain=Math.max(0,state.remain+delta);if(state.remain===0)state.running=false});
$('#start').onclick=()=>act(()=>{if(!state.running&&state.remain===0)state.remain=state.minutes*60;state.running=!state.running});$('#reset').onclick=()=>act(()=>{state.running=false;state.remain=state.minutes*60});for(const[id,d]of[['prev',-1],['next',1]])$('#'+id).onclick=()=>act(()=>{state.period=Math.min(state.periods,Math.max(1,state.period+d));state.running=false;state.remain=state.minutes*60});$('#all').onclick=()=>act(()=>{const on=!state.armed.some((a,i)=>a&&state.p[i]>0);for(let i=0;i<4;i++)state.armed[i]=on&&state.active[i]&&state.p[i]>0});
for(const[id,key,max]of[['custom-periods','periods',99],['custom-minutes','minutes',999]])$('#'+id).onchange=()=>{const n=+$('#'+id).value;if(!Number.isInteger(n)||n<1||n>max){$('#'+id).setCustomValidity('Enter 1–'+max);$('#'+id).reportValidity();return}$('#'+id).setCustomValidity('');act(()=>{state[key]=n;if(key==='periods')state.period=Math.min(state.period,n);else{state.remain=n*60;state.running=false}})};
let field=1;try{field=Number(localStorage.getItem('resolute-field'))||1}catch(e){}if(![1,2,3,4].includes(field))field=1;
function fieldDefaults(n){return ['Team '+(n*2-1),'Team '+n*2]}
function saveField(){try{localStorage.setItem('resolute-field-score-'+field,JSON.stringify({team1:$('#team1').value,team2:$('#team2').value,score1:$('#score1').value,score2:$('#score2').value}))}catch(e){}}
function loadField(){const names=fieldDefaults(field);let data={team1:names[0],team2:names[1],score1:'0',score2:'0'};try{const stored=localStorage.getItem('resolute-field-score-'+field);if(stored)data={...data,...JSON.parse(stored)};else if(field===1){for(const id of['team1','team2','score1','score2']){const value=localStorage.getItem('resolute-'+id);if(value!==null)data[id]=value}}}catch(e){}for(const id of['team1','team2','score1','score2'])$('#'+id).value=data[id];$('#field').value=field;$('#team1-label').textContent='Team 1';$('#team2-label').textContent='Team 2';$('#score1').setAttribute('aria-label',names[0]+' score');$('#score2').setAttribute('aria-label',names[1]+' score');$('#score-heading').textContent='FIELD '+field+' · FINAL SCORE REPORT';updateFieldNames();render()}
function fieldRecord(n){const defaults=fieldDefaults(n);let data={team1:defaults[0],team2:defaults[1],score1:'0',score2:'0'};try{const v=localStorage.getItem('resolute-field-score-'+n);if(v)data={...data,...JSON.parse(v)}}catch(e){}return data}
function updateFieldNames(){for(let n=1;n<=4;n++){const data=fieldRecord(n);$('#field').options[n-1].textContent='Field '+n+' · '+data.team1+' vs '+data.team2}$('#team1-label').textContent='Team 1';$('#team2-label').textContent='Team 2'}
$('#edit-fields').onclick=()=>{saveField();const container=$('#edit-team-fields');container.replaceChildren();for(let n=1;n<=4;n++){const data=fieldRecord(n),group=document.createElement('fieldset'),legend=document.createElement('legend');legend.textContent='Field '+n;group.append(legend);for(let side=1;side<=2;side++){const label=document.createElement('label'),input=document.createElement('input');input.id='edit-field-'+n+'-team-'+side;input.name=input.id;input.value=data['team'+side];input.maxLength=60;input.required=true;label.htmlFor=input.id;label.textContent='Team '+side;group.append(label,input)}container.append(group)}$('#edit-dialog').showModal()};
$('#cancel-edit').onclick=()=>$('#edit-dialog').close();$('#edit-form').onsubmit=e=>{e.preventDefault();const edits=[];for(let n=1;n<=4;n++){const a=$('#edit-field-'+n+'-team-1'),b=$('#edit-field-'+n+'-team-2');for(const input of[a,b]){input.setCustomValidity(input.value.trim()?'':'Enter a team name');if(!input.reportValidity())return}edits.push({...fieldRecord(n),team1:a.value.trim(),team2:b.value.trim()})}try{edits.forEach((data,i)=>localStorage.setItem('resolute-field-score-'+(i+1),JSON.stringify(data)))}catch(err){alert('Unable to save team names on this device.');return}loadField();updateFieldNames();$('#edit-dialog').close()};
$('#reset-fields').onclick=()=>{try{for(let n=1;n<=4;n++){const names=fieldDefaults(n);localStorage.setItem('resolute-field-score-'+n,JSON.stringify({team1:names[0],team2:names[1],score1:'0',score2:'0'}))}localStorage.setItem('resolute-field','1');for(const id of['team1','team2','score1','score2'])localStorage.removeItem('resolute-'+id)}catch(e){$('#note').textContent='Unable to reset fields on this device.';return}field=1;loadField();$('#note').textContent='All four fields reset to default names and zero scores.'};
$('#field').onchange=()=>{saveField();field=Number($('#field').value);try{localStorage.setItem('resolute-field',String(field))}catch(e){}loadField()};for(const id of['team1','team2','score1','score2'])$('#'+id).oninput=()=>{saveField();updateFieldNames();render()};try{$('#phone').value=localStorage.getItem('resolute-phone')||''}catch(e){}$('#phone').oninput=()=>{try{localStorage.setItem('resolute-phone',$('#phone').value)}catch(e){}};loadField();
$('#send').onclick=()=>{const phone=$('#phone').value.replace(/[\s().-]/g,'');if(!/^\+?\d{7,15}$/.test(phone)){$('#note').textContent='Enter a valid phone number.';$('#phone').focus();return}location.href='sms:'+phone+'&body='+encodeURIComponent(message());$('#note').textContent='Review and send in Messages.'};
advance();render();setInterval(()=>{advance(true);render()},100);setInterval(save,1000);document.addEventListener('visibilitychange',()=>{advance();save();if(document.visibilityState==='visible'&&state.running)unlock()});window.addEventListener('pagehide',save);if(window.matchMedia('(display-mode: standalone)').matches||navigator.standalone)$('#install').hidden=true;
if(document.modelContext?.registerTool){try{document.modelContext.registerTool({name:'read_timer_state',description:'Read the game and penalty clocks.',inputSchema:{type:'object',properties:{},additionalProperties:false},annotations:{readOnlyHint:true},execute(){advance();render();return{period:state.period,periods:state.periods,gameSeconds:Math.ceil(state.remain),running:state.running,penalties:state.p.map((p,i)=>({seconds:Math.ceil(p),enabled:state.armed[i]}))}}})}catch(e){}}
})();
